"""NRS 484B.307(5)(a) straight-arrow controller and source guards.

CARLA's generic green state does not identify an arrow indication. Native
capture must supply a verified signal-head description before any attempt.
"""
import argparse
import json
import math
from pathlib import Path

ROOT=Path(__file__).resolve().parent


def load_scene(path=None):
    scene=json.loads(Path(path or ROOT/'scene.json').read_text())
    if (scene['law_id'],scene['cell_id'],scene['actor']) != (
            'NRS-484B-307-5a','C111125','motor_vehicle_driver'):
        raise ValueError('wrong frozen assignment identity')
    if scene['approach_x_m']>=scene['stop_line_x_m'] or scene['exit_x_m']<=scene['intersection_x_max_m']:
        raise ValueError('straight route must approach stop line and clear intersection')
    if scene['intersection_x_min_m']>=scene['intersection_x_max_m']:
        raise ValueError('invalid intersection bounds')
    return scene


def require_sole_straight_arrow(signal, *, head_id, frame):
    """Read back one source-verified facing head; reject a generic green bulb."""
    if signal.get('source_verified') is not True or not signal.get('source_ref'):
        raise ValueError('sole arrow lacks source-verified signal head')
    if signal.get('head_id')!=head_id or signal.get('observed_frame')!=frame:
        raise ValueError('signal aspect is not bound to the facing head and frame')
    indications=signal.get('illuminated_indications')
    if indications!=[{'color':'green','shape':'arrow','direction':'straight'}]:
        raise ValueError('facing signal is not a sole green straight-through arrow')
    return signal


def select_facing_head(scene, heads, *, frame):
    """Select a source-verified facing arrow head by a predeclared slot.

    The alternate slot is engineering redundancy, never an outcome selector.
    A Native adapter must populate heads from original per-frame signal sources.
    """
    slot=scene.get('candidate_head_slot',0)
    if type(slot) is not int or slot<0:
        raise ValueError('invalid predeclared head slot')
    facing=[head for head in heads if head.get('faces_ego_approach') is True]
    if any(type(head.get('head_id')) is not int for head in facing):
        raise ValueError('facing signal head lacks stable integer ID')
    facing.sort(key=lambda head:head['head_id'])
    if len({head['head_id'] for head in facing})!=len(facing):
        raise ValueError('duplicate facing signal head ID')
    if slot>=len(facing):
        raise ValueError('selected facing signal head slot absent')
    chosen=facing[slot]
    return require_sole_straight_arrow(chosen,head_id=chosen['head_id'],frame=frame)


def body_bounds(vertices):
    if not isinstance(vertices,list) or len(vertices)<4 or any(
            not isinstance(v,list) or len(v)<2 or
            any(type(x) not in (int,float) or not math.isfinite(x) for x in v[:2])
            for v in vertices):
        raise ValueError('missing finite participant body footprint')
    return (min(v[0] for v in vertices),min(v[1] for v in vertices),
            max(v[0] for v in vertices),max(v[1] for v in vertices))


def overlaps(vertices,region):
    left,bottom,right,top=body_bounds(vertices)
    if len(region)!=4 or any(type(x) not in (int,float) or not math.isfinite(x) for x in region):
        raise ValueError('invalid intersection or crosswalk bounds')
    a,b,c,d=region
    if a>=c or b>=d:raise ValueError('invalid region bounds')
    return left<=c and right>=a and bottom<=d and top>=b


def yield_decision(scene, participants, *, signal_exhibited_frame, current_frame):
    """Hold at the line while a lawfully present participant still occupies it.

    Lawful presence is an independently sourced input, never inferred from a
    pedestrian's or vehicle's position alone.
    """
    if current_frame<signal_exhibited_frame:raise ValueError('signal exhibition time is in the future')
    occupied=[]
    regions=[scene['intersection_bounds_m'],*scene['adjacent_crosswalk_bounds_m']]
    for item in participants:
        if not {'id','role','body_vertices_m','lawful_presence_source','lawfully_present'}<=item.keys():
            raise ValueError('participant lawfulness or body source missing')
        if item['role'] not in ('vehicle','pedestrian'):
            raise ValueError('unsupported participant role')
        if not item['lawful_presence_source']:
            raise ValueError('lawful presence source missing')
        body_bounds(item['body_vertices_m'])
        if item['lawfully_present'] and any(overlaps(item['body_vertices_m'],r) for r in regions):
            occupied.append(item['id'])
    return {'hold_at_stop_line':bool(occupied),'occupied_by':occupied,
            'signal_exhibited_frame':signal_exhibited_frame,'decision_frame':current_frame,
            'method':'original participant body overlap and independently sourced lawful presence'}


def command(scene, ego_front_x_m, decision):
    if not isinstance(decision,dict) or 'hold_at_stop_line' not in decision:
        raise ValueError('missing yield decision')
    if decision['hold_at_stop_line'] and ego_front_x_m>scene['stop_line_x_m']:
        raise ValueError('ego already crossed stop line before yield cleared')
    return {'throttle':0.0 if decision['hold_at_stop_line'] else .25,
            'brake':1.0 if decision['hold_at_stop_line'] else 0.0,
            'steer':0.0,'intended_maneuver':'straight'}


def spawn_scene(world,scene,transform_factory):
    """Create distinct ego, vehicle and pedestrian actors for the exact case.

    The occupied case places both participant classes in governed regions.
    Lawful presence still requires independent original phase/right-of-way source.
    """
    library=world.get_blueprint_library()
    specs=[('ego','vehicle.*',scene['approach_x_m'],0),
           ('vehicle','vehicle.*',0 if scene['participant_occupancy_setup']=='lawfully_present' else 35,0),
           ('pedestrian','walker.pedestrian.*',9 if scene['participant_occupancy_setup']=='lawfully_present' else 35,0)]
    if scene['participant_occupancy_setup'] not in ('clear','lawfully_present'):
        raise ValueError('unsupported occupancy setup')
    actors={}
    try:
        for name,pattern,x,y in specs:
            matches=list(library.filter(pattern))
            if not matches:raise ValueError('missing Native actor blueprint: '+pattern)
            actors[name]=world.spawn_actor(matches[0],transform_factory(x,y,0,0))
        if len({id(actor) for actor in actors.values()})!=len(actors):
            raise ValueError('Native world reused an actor for distinct roles')
    except BaseException:
        for actor in reversed(list(actors.values())):
            if hasattr(actor,'destroy'):actor.destroy()
        raise
    return actors


def participant_motion(scene, elapsed_s):
    """Native control targets that clear both governed regions after a hold.

    The vehicle crosses northbound through the intersection; the pedestrian
    crosses the adjacent crosswalk. This is a construction policy only. Body
    positions and lawful presence must still be read back from original sources.
    """
    if type(elapsed_s) not in (int,float) or not math.isfinite(elapsed_s) or elapsed_s<0:
        raise ValueError('invalid participant elapsed time')
    if scene['participant_occupancy_setup']=='clear':
        return {'vehicle_velocity_xyz_mps':(0.,0.,0.),
                'pedestrian_direction_xyz':(0.,0.,0.),'pedestrian_speed_mps':0.}
    if scene['participant_occupancy_setup']!='lawfully_present':
        raise ValueError('unsupported occupancy setup')
    # The target motion moves bodies beyond the y=5 m region boundary within
    # the 30 s capture. A Native controller must stop them after readback clears.
    return {'vehicle_velocity_xyz_mps':(0.,2.,0.),
            'pedestrian_direction_xyz':(0.,1.,0.),'pedestrian_speed_mps':1.5}


def apply_participant_motion(scene, actors, carla, elapsed_s):
    """Issue the occupied/clear construction controls to owned Native actors."""
    motion=participant_motion(scene,elapsed_s)
    vx,vy,vz=motion['vehicle_velocity_xyz_mps']
    dx,dy,dz=motion['pedestrian_direction_xyz']
    actors['vehicle'].set_target_velocity(carla.Vector3D(x=vx,y=vy,z=vz))
    actors['pedestrian'].apply_control(carla.WalkerControl(
        direction=carla.Vector3D(x=dx,y=dy,z=dz),speed=motion['pedestrian_speed_mps']))
    return motion


def check():
    scene=load_scene()
    assert scene['approach_x_m']<scene['stop_line_x_m']<scene['intersection_x_max_m']<scene['exit_x_m']
    heads=[{'source_verified':True,'source_ref':'synthetic/check-only',
            'head_id':head_id,'observed_frame':0,'faces_ego_approach':True,
            'illuminated_indications':[{'color':'green','shape':'arrow','direction':'straight'}]}
           for head_id in (7,8)]
    chosen=select_facing_head(scene,heads,frame=0)
    print(json.dumps({'geometry_checked':True,'selected_synthetic_head_id':chosen['head_id'],
                      'sole_arrow_source_verification_pending':True}))


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    parser.add_argument('--output-dir')
    parser.add_argument('--host',default='127.0.0.1')
    parser.add_argument('--port',type=int,default=2000)
    args=parser.parse_args()
    if args.check:check();return
    if not args.output_dir:parser.error('--output-dir is required for Native capture')
    from native_capture import run_native
    run_native(load_scene(),args.output_dir,args.host,args.port)


if __name__=='__main__':main()

"""Original CARLA capture for the straight-arrow cases.

CARLA's generic traffic-light state is retained as a source observation. It is
never promoted to a sole-arrow or lawful-presence fact without another source.
"""
import hashlib
import json
import queue
import subprocess
from pathlib import Path


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def write(path, value):
    Path(path).write_text(json.dumps(value, indent=2, allow_nan=False) + '\n')


def vertices(actor):
    return [[point.x, point.y, point.z] for point in
            actor.bounding_box.get_world_vertices(actor.get_transform())]


def signal_snapshot(lights, frame):
    """Retain raw actor states; a generic Green state proves no arrow shape."""
    observed=[]
    for light in lights:
        transform=light.get_transform()
        observed.append({'actor_id':int(light.id),
                         'state':str(light.get_state()),
                         'blueprint_id':str(light.type_id),
                         'position_m':[transform.location.x,transform.location.y,transform.location.z],
                         'yaw_deg':transform.rotation.yaw})
    observed.sort(key=lambda item:item['actor_id'])
    if len({item['actor_id'] for item in observed})!=len(observed):
        raise ValueError('duplicate Native traffic-light actor ID')
    return {'frame':frame,'candidate_lights':observed,
            'facing_head_id':None,
            'aspect':{'source_verified':False,'source_ref':'original CARLA actor state only',
                      'head_id':None,'observed_frame':frame,
                      'illuminated_indications':[]},
            'limitation':'CARLA actor state and blueprint ID do not establish a sole straight arrow or facing head'}


def map_context(mapping, scene, carla):
    """Check the authored straight route against actual driving waypoints."""
    points=[]
    for x in (scene['approach_x_m'],scene['stop_line_x_m'],scene['exit_x_m']):
        waypoint=mapping.get_waypoint(carla.Location(x=x,y=0,z=0))
        if waypoint is None or abs(waypoint.transform.location.x-x)>1.5 or abs(waypoint.transform.location.y)>1.5:
            raise ValueError('authored straight route lacks matching Native driving waypoint')
        points.append(waypoint)
    if len({(point.road_id,point.lane_id) for point in points})!=1:
        raise ValueError('authored straight route changes road or lane')
    return {'source':'native_map','road_id':points[0].road_id,'lane_id':points[0].lane_id,
            'stop_line_x_m':scene['stop_line_x_m'],
            'intersection_bounds_m':scene['intersection_bounds_m'],
            'adjacent_crosswalk_bounds_m':scene['adjacent_crosswalk_bounds_m'],
            'facing_head_id':None,
            'geometry_limitation':'Authored region coordinates require Native map and visible asset review',
            'lawful_presence_source_verified':False}


class CameraBank:
    SPECS=(('overview',1920,1080,(0,0,45,-90)),
           ('approach',1280,720,(-15,-12,12,-25)),
           ('reference_corner',1280,720,(4,4,12,-45)),
           ('driver_reference',1280,720,(0,0,2,0)))

    def __init__(self,world,ego,output,carla):
        self.sensors=[];self.encoders={};self.queues={};self.errors=[]
        try:self._start(world,ego,output,carla)
        except BaseException:
            try:self.close()
            except BaseException:pass
            raise

    def _start(self,world,ego,output,carla):
        library=world.get_blueprint_library()
        for name,width,height,pose in self.SPECS:
            blueprint=library.find('sensor.camera.rgb')
            blueprint.set_attribute('image_size_x',str(width))
            blueprint.set_attribute('image_size_y',str(height))
            blueprint.set_attribute('fov','90')
            x,y,z,pitch=pose
            transform=carla.Transform(carla.Location(x=x,y=y,z=z),carla.Rotation(pitch=pitch))
            sensor=world.spawn_actor(blueprint,transform,attach_to=ego if name=='driver_reference' else None)
            self.sensors.append(sensor)
            frames=queue.Queue(maxsize=4);self.queues[name]=frames
            def receive(image,q=frames,label=name):
                try:q.put_nowait(image)
                except queue.Full:self.errors.append('camera queue overflow: '+label)
            sensor.listen(receive)
            command=['ffmpeg','-nostdin','-hide_banner','-loglevel','error','-n',
                     '-f','rawvideo','-pixel_format','bgra','-video_size',f'{width}x{height}',
                     '-framerate','20','-i','pipe:0','-an','-c:v','ffv1','-pix_fmt','bgra',
                     str(output/(name+'.mkv'))]
            self.encoders[name]=subprocess.Popen(command,stdin=subprocess.PIPE,stderr=subprocess.DEVNULL)

    def append(self,frame):
        if self.errors:raise RuntimeError('; '.join(self.errors))
        for name,_,_,_ in self.SPECS:
            image=self.queues[name].get(timeout=15)
            if image.frame!=frame:raise RuntimeError(f'{name} camera frame differs from world frame')
            self.encoders[name].stdin.write(image.raw_data)

    def close(self):
        failures=[]
        for sensor in reversed(self.sensors):
            try:sensor.stop()
            except BaseException as exc:failures.append(repr(exc))
        for name,process in self.encoders.items():
            try:
                if process.stdin and not process.stdin.closed:process.stdin.close()
                if process.wait(timeout=180)!=0:failures.append('camera encoder failed: '+name)
            except BaseException as exc:failures.append(repr(exc))
        for sensor in reversed(self.sensors):
            try:sensor.destroy()
            except BaseException as exc:failures.append(repr(exc))
        if failures:raise RuntimeError('; '.join(failures))


def run_native(scene,output,host,port):
    import carla
    from pipeline_capture import PipelineCapture
    from worker_exchange.native_output import FrameMap,write_result,seal_capture
    from worker_exchange.world_restore import fields,equal
    from runner import apply_participant_motion,spawn_scene

    output=Path(output).resolve()
    if not output.is_dir():raise ValueError('Native attempt directory must already exist')
    write(output/'acquisition-provenance.json',{'provenance_kind':'native','diagnostic_fixture':False,
          'method':'original CARLA live capture; generic signal state retained without arrow inference'})
    client=carla.Client(host,port);client.set_timeout(30)
    world=client.get_world();original_settings=world.get_settings()
    actors={};cameras=None;capture=None;frame_map=None
    phase='initializing';error=None;restored=False;rows=[]
    try:
        context=map_context(world.get_map(),scene,carla)
        settings=world.get_settings();settings.synchronous_mode=True;settings.fixed_delta_seconds=.05
        world.apply_settings(settings)
        def transform(x,y,_,yaw):
            wp=world.get_map().get_waypoint(carla.Location(x=x,y=y,z=0))
            if wp is None:raise ValueError('Native spawn lacks map waypoint')
            return carla.Transform(carla.Location(x=x,y=y,z=wp.transform.location.z+.5),
                                   carla.Rotation(yaw=yaw))
        actors=spawn_scene(world,scene,transform)
        ego=actors['ego']
        lights=list(world.get_actors().filter('traffic.traffic_light*'))
        context['candidate_light_actor_ids']=sorted(int(light.id) for light in lights)
        write(output/'intersection-context.json',context)
        cameras=CameraBank(world,ego,output,carla)
        capture=PipelineCapture(client,ego,output,scene['case_id'])
        frame_map=FrameMap(output/'video_frames.jsonl')
        phase='capturing'
        count=round(scene['duration_s']*scene['capture_rate_hz'])
        with (output/'signal-head-history.jsonl').open('x',buffering=1) as signals, \
             (output/'ego-body-history.jsonl').open('x',buffering=1) as bodies, \
             (output/'participant-history.jsonl').open('x',buffering=1) as participants:
            for index in range(count):
                # No original source currently establishes a sole arrow or lawful
                # presence, so the ego remains held upstream of the stop line.
                ego.apply_control(carla.VehicleControl(throttle=0,brake=1,steer=0))
                apply_participant_motion(scene,actors,carla,index/scene['capture_rate_hz'])
                frame=world.tick();snapshot=world.get_snapshot()
                if snapshot.frame!=frame:raise RuntimeError('world tick identity differs')
                time_s=snapshot.timestamp.elapsed_seconds
                capture.capture(frame,time_s);cameras.append(frame);frame_map.append(frame,time_s)
                signal=signal_snapshot(lights,frame)
                signal.update(time_s=time_s)
                ego_row={'frame':frame,'time_s':time_s,'body_vertices_m':vertices(ego),
                         'heading_deg':ego.get_transform().rotation.yaw}
                people=[]
                for name,role in (('vehicle','vehicle'),('pedestrian','pedestrian')):
                    people.append({'id':int(actors[name].id),'role':role,
                                   'body_vertices_m':vertices(actors[name]),
                                   'lawfully_present':None,
                                   'lawful_presence_source':None})
                people_row={'frame':frame,'time_s':time_s,'participants':people}
                signals.write(json.dumps(signal,allow_nan=False)+'\n')
                bodies.write(json.dumps(ego_row,allow_nan=False)+'\n')
                participants.write(json.dumps(people_row,allow_nan=False)+'\n')
                rows.append(frame)
        phase='closing'
        capture.close();capture=None
        frame_map.close();frame_map=None
        cameras.close();cameras=None
        source_names=['trace.jsonl','video_frames.jsonl','signal-head-history.jsonl',
                      'ego-body-history.jsonl','participant-history.jsonl','intersection-context.json',
                      'road.xodr','carla_recorder.log',*[name+'.mkv' for name,*_ in CameraBank.SPECS]]
        write(output/'acquisition.json',{name:{'kind':'original_native','sha256':sha(output/name)} for name in source_names})
        write_result(output,{'case_id':scene['case_id'],
          'measured_values':{'sole_arrow_verified':False,'lawful_presence_verified':False},
          'target_checks':[{'target':'original straight-arrow source acquisition','requested':True,
                            'measured':False,'method':'CARLA actor state and asset inventory',
                            'tolerance':0,'matched':False,'physical_cause_confirmed':False,
                            'cause_evidence':'generic CARLA traffic light state does not identify arrow shape'}],
          'setup_confirmed':False,'behavior_attempted':False,'maneuver_completed':False,
          'termination_reason':'planned_duration_without_verified_arrow_source',
          'physical_failure_flags':['sole_arrow_source_unverified','lawful_presence_source_unverified'],
          'trace_reference':'trace.jsonl',
          'video_references':[name+'.mkv' for name,*_ in CameraBank.SPECS],
          'video_frame_map_reference':'video_frames.jsonl',
          'recording_description':{'summary':'Original held approach and participant motion; arrow source unverified'},
          'recording_evidence':{'acquisition':'acquisition.json'},
          'realized_observables':{'frame_count':len(rows),'candidate_lights':len(lights)}})
        phase='sealed'
    except BaseException as exc:
        error=repr(exc)
        raise
    finally:
        cleanup=[]
        for resource in (capture,frame_map,cameras):
            if resource:
                try:resource.close()
                except BaseException as exc:cleanup.append(repr(exc))
        for actor in reversed(list(actors.values())):
            try:actor.destroy()
            except BaseException as exc:cleanup.append(repr(exc))
        try:
            world.apply_settings(original_settings)
            restored=all(equal(fields(world.get_settings()).get(key),value)
                         for key,value in fields(original_settings).items())
        except BaseException as exc:cleanup.append(repr(exc))
        if phase=='sealed' and not cleanup and restored:
            seal_capture(output,frames=len(rows),restoration={'restored':True,
                'settings_readback':'synchronous_mode and fixed_delta_seconds restored'},errors=[],
                encoder_exit_codes={name:0 for name,*_ in CameraBank.SPECS},context={'arrow':False})
        else:
            write(output/'native-run-status.json',{'phase':phase,
                  'errors':[value for value in [error,*cleanup] if value],
                  'settings_restored':restored})
            if phase=='sealed':raise RuntimeError('Native cleanup or settings restoration failed')

import importlib.util
from pathlib import Path
import unittest

ROOT=Path(__file__).resolve().parents[1]
spec=importlib.util.spec_from_file_location('arrow_runner',ROOT/'runner.py')
runner=importlib.util.module_from_spec(spec);spec.loader.exec_module(runner)


def participant(identifier,role,x,y,lawful=True):
    return {'id':identifier,'role':role,
            'body_vertices_m':[[x,y,0],[x+1,y,0],[x+1,y+1,0],[x,y+1,0]],
            'lawfully_present':lawful,'lawful_presence_source':'original phase and right-of-way context'}


class ArrowControllerTests(unittest.TestCase):
    def setUp(self):self.scene=runner.load_scene()
    def test_spawns_clear_and_occupied_actor_geometry(self):
        class Actor:
            def destroy(self):self.destroyed=True
        class Library:
            def filter(self,pattern):return [pattern]
        class World:
            def __init__(self):self.calls=[]
            def get_blueprint_library(self):return Library()
            def spawn_actor(self,blueprint,transform):
                self.calls.append((blueprint,transform));return Actor()
        for occupancy,positions in [('clear',(-30,35,35)),('lawfully_present',(-30,0,9))]:
            world=World();scene=dict(self.scene,participant_occupancy_setup=occupancy)
            actors=runner.spawn_scene(world,scene,lambda *values:values)
            self.assertEqual(set(actors),{'ego','vehicle','pedestrian'})
            self.assertEqual(tuple(call[1][0] for call in world.calls),positions)
            self.assertEqual(world.calls[-1][0],'walker.pedestrian.*')
    def test_occupied_participants_have_bounded_clearance_motion(self):
        occupied=dict(self.scene,participant_occupancy_setup='lawfully_present')
        clear=dict(self.scene,participant_occupancy_setup='clear')
        move=runner.participant_motion(occupied,0)
        self.assertGreater(move['vehicle_velocity_xyz_mps'][1],0)
        self.assertGreater(move['pedestrian_speed_mps'],0)
        self.assertGreater(move['pedestrian_direction_xyz'][1],0)
        self.assertEqual(runner.participant_motion(clear,0)['vehicle_velocity_xyz_mps'],(0.,0.,0.))
        with self.assertRaises(ValueError):runner.participant_motion(occupied,float('nan'))
        class Actor:
            def set_target_velocity(self,value):self.velocity=value
            def apply_control(self,value):self.control=value
        class Carla:
            @staticmethod
            def Vector3D(**value):return value
            @staticmethod
            def WalkerControl(**value):return value
        actors={'vehicle':Actor(),'pedestrian':Actor()}
        runner.apply_participant_motion(occupied,actors,Carla,2.)
        self.assertEqual(actors['vehicle'].velocity['y'],2.)
        self.assertEqual(actors['pedestrian'].control['speed'],1.5)
    def test_predeclared_alternate_head_selection(self):
        def head(ident,verified=True,facing=True):
            return {'source_verified':verified,'source_ref':'original/head-stream',
                    'head_id':ident,'observed_frame':18,'faces_ego_approach':facing,
                    'illuminated_indications':[{'color':'green','shape':'arrow','direction':'straight'}]}
        heads=[head(8),head(7)]
        primary=dict(self.scene,candidate_head_slot=0)
        self.assertEqual(runner.select_facing_head(primary,heads,frame=18)['head_id'],7)
        alternate=dict(self.scene,candidate_head_slot=1)
        self.assertEqual(runner.select_facing_head(alternate,heads,frame=18)['head_id'],8)
        with self.assertRaises(ValueError):
            runner.select_facing_head(alternate,[head(7),head(8,verified=False)],frame=18)
        with self.assertRaises(ValueError):
            runner.select_facing_head(alternate,[head(7),head(8,facing=False)],frame=18)
        with self.assertRaises(ValueError):
            runner.select_facing_head(primary,[head(7,verified=False),head(8)],frame=18)
        self.assertEqual(runner.select_facing_head(alternate,[head(7,verified=False),head(8)],frame=18)['head_id'],8)
    def test_sole_arrow_requires_exact_facing_source(self):
        aspect={'source_verified':True,'source_ref':'native/head-readback.json',
                'head_id':7,'observed_frame':18,
                'illuminated_indications':[{'color':'green','shape':'arrow','direction':'straight'}]}
        self.assertIs(runner.require_sole_straight_arrow(aspect,head_id=7,frame=18),aspect)
        for change in ({'source_verified':False},
                       {'illuminated_indications':[{'color':'green','shape':'circle','direction':'all'}]},
                       {'illuminated_indications':aspect['illuminated_indications']+[{'color':'green','shape':'arrow','direction':'left'}]},
                       {'head_id':8},{'observed_frame':19}):
            with self.assertRaises(ValueError):
                runner.require_sole_straight_arrow(dict(aspect,**change),head_id=7,frame=18)
    def test_yield_for_vehicle_and_pedestrian_in_governed_regions(self):
